import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiCalendar,
  FiMapPin,
  FiImage,
  FiUploadCloud,
  FiX,
} from 'react-icons/fi';

import api from '../../services/api';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import { useLanguage } from '../../contexts/LanguageContext';


const AdminEvents = () => {

  // =====================================================
  // LANGUAGE
  // =====================================================

  const {
    t,
    language,
  } = useLanguage();


  // =====================================================
  // STATE
  // =====================================================

  const [events, setEvents] = useState([]);

  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);

  const [editingEvent, setEditingEvent] = useState(null);

  const [submitting, setSubmitting] = useState(false);


  const [formData, setFormData] = useState({
    title: '',
    description: '',
    date: '',
    location: '',
    is_upcoming: true,
    is_past: false,
  });


  const [imageFile, setImageFile] = useState(null);

  const [imagePreview, setImagePreview] = useState('');


  // =====================================================
  // FETCH EVENTS
  // =====================================================

  useEffect(() => {

    fetchEvents();

  }, []);


  const fetchEvents = async () => {

    try {

      setLoading(true);


      const response = await api.get(
        '/api/events/'
      );


      setEvents(
        Array.isArray(response.data)
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Error loading events:',
        error
      );


      toast.error(
        error.response?.data?.detail ||
          t('events.loadFailed')
      );

    } finally {

      setLoading(false);

    }

  };


  // =====================================================
  // DATE HELPERS
  // =====================================================

  const toDateInput = (value) => {

    if (!value) {
      return '';
    }


    return String(value).split('T')[0];

  };


  // =====================================================
  // FORMAT DATE
  // =====================================================

  const formatDate = (value) => {

    if (!value) {
      return '-';
    }


    const dateOnly = String(value).split('T')[0];


    const parts = dateOnly.split('-');


    if (parts.length !== 3) {
      return '-';
    }


    const [
      year,
      month,
      day,
    ] = parts;


    if (
      !year ||
      !month ||
      !day
    ) {
      return '-';
    }


    const date = new Date(
      Number(year),
      Number(month) - 1,
      Number(day)
    );


    if (
      Number.isNaN(
        date.getTime()
      )
    ) {
      return '-';
    }


    return date.toLocaleDateString(
      language === 'km'
        ? 'km-KH'
        : 'en-GB',
      {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
      }
    );

  };


  // =====================================================
  // RESET FORM
  // =====================================================

  const resetForm = () => {

    setEditingEvent(null);


    setFormData({
      title: '',
      description: '',
      date: '',
      location: '',
      is_upcoming: true,
      is_past: false,
    });


    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(null);

    setImagePreview('');

  };


  // =====================================================
  // OPEN CREATE MODAL
  // =====================================================

  const handleAdd = () => {

    resetForm();

    setModalOpen(true);

  };


  // =====================================================
  // CLOSE MODAL
  // =====================================================

  const handleCloseModal = () => {

    setModalOpen(false);

    resetForm();

  };


  // =====================================================
  // HANDLE INPUT
  // =====================================================

  const handleChange = (e) => {

    const {
      name,
      value,
    } = e.target;


    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));

  };


  // =====================================================
  // IMAGE CHANGE
  // =====================================================

  const handleImageChange = (e) => {

    const file = e.target.files?.[0];


    if (!file) {
      return;
    }


    if (
      !file.type.startsWith('image/')
    ) {

      toast.error(
        t('events.selectImage')
      );

      return;

    }


    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(file);


    const preview =
      URL.createObjectURL(file);


    setImagePreview(preview);

  };


  // =====================================================
  // REMOVE SELECTED IMAGE
  // =====================================================

  const removeSelectedImage = () => {

    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(null);


    if (editingEvent?.image) {

      setImagePreview(
        editingEvent.image
      );

    } else if (
      editingEvent?.image_url
    ) {

      setImagePreview(
        editingEvent.image_url
      );

    } else {

      setImagePreview('');

    }

  };


  // =====================================================
  // CREATE / UPDATE
  // =====================================================

  const handleSubmit = async (e) => {

    e.preventDefault();


    // ===================================================
    // VALIDATION
    // ===================================================

    if (
      !formData.title.trim()
    ) {

      toast.error(
        t('events.titleRequired')
      );

      return;

    }


    if (!formData.date) {

      toast.error(
        t('events.dateRequired')
      );

      return;

    }


    if (
      !/^\d{4}-\d{2}-\d{2}$/.test(
        formData.date
      )
    ) {

      toast.error(
        t('events.invalidDate')
      );

      return;

    }


    try {

      setSubmitting(true);


      const payload =
        new FormData();


      // =================================================
      // TEXT DATA
      // =================================================

      payload.append(
        'title',
        formData.title.trim()
      );


      payload.append(
        'description',
        formData.description?.trim() || ''
      );


      payload.append(
        'date',
        formData.date
      );


      payload.append(
        'location',
        formData.location?.trim() || ''
      );


      payload.append(
        'is_upcoming',
        String(
          formData.is_upcoming
        )
      );


      payload.append(
        'is_past',
        String(
          formData.is_past
        )
      );


      // =================================================
      // IMAGE
      // =================================================

      if (imageFile) {

        payload.append(
          'image_file',
          imageFile
        );

      }


      // =================================================
      // UPDATE EVENT
      // =================================================

      if (editingEvent) {

        await api.put(
          `/api/events/${editingEvent.id}`,
          payload,
          {
            headers: {
              'Content-Type':
                'multipart/form-data',
            },
          }
        );


        toast.success(
          t(
            'events.updatedSuccess'
          )
        );

      }


      // =================================================
      // CREATE EVENT
      // =================================================

      else {

        await api.post(
          '/api/events/',
          payload,
          {
            headers: {
              'Content-Type':
                'multipart/form-data',
            },
          }
        );


        toast.success(
          t(
            'events.createdSuccess'
          )
        );

      }


      handleCloseModal();


      await fetchEvents();

    } catch (error) {

      console.error(
        'Event operation error:',
        error
      );


      const detail =
        error.response?.data?.detail;


      if (
        typeof detail === 'string'
      ) {

        toast.error(detail);

      } else if (
        Array.isArray(detail)
      ) {

        toast.error(
          detail
            .map(
              (item) =>
                item.msg
            )
            .join(', ')
        );

      } else {

        toast.error(
          t(
            'common.operationFailed'
          )
        );

      }

    } finally {

      setSubmitting(false);

    }

  };


  // =====================================================
  // EDIT
  // =====================================================

  const handleEdit = (event) => {

    setEditingEvent(event);


    setFormData({

      title:
        event.title || '',


      description:
        event.description || '',


      date:
        toDateInput(
          event.date
        ),


      location:
        event.location || '',


      is_upcoming:
        Boolean(
          event.is_upcoming
        ),


      is_past:
        Boolean(
          event.is_past
        ),

    });


    setImageFile(null);


    setImagePreview(
      event.image ||
        event.image_url ||
        ''
    );


    setModalOpen(true);

  };


  // =====================================================
  // DELETE
  // =====================================================

  const handleDelete = async (id) => {

    const confirmed =
      window.confirm(
        t(
          'events.deleteConfirm'
        )
      );


    if (!confirmed) {
      return;
    }


    try {

      await api.delete(
        `/api/events/${id}`
      );


      toast.success(
        t(
          'events.deletedSuccess'
        )
      );


      await fetchEvents();

    } catch (error) {

      console.error(
        'Delete event error:',
        error
      );


      toast.error(
        typeof error.response?.data?.detail ===
          'string'
          ? error.response.data.detail
          : t(
              'events.deleteFailed'
            )
      );

    }

  };


  // =====================================================
  // TABLE COLUMNS
  // =====================================================

  const columns = [

    // ===================================================
    // EVENT TITLE
    // ===================================================

    {
      key: 'title',

      label: t(
        'events.eventColumn'
      ),


      render: (value) => (

        <div className="min-w-[180px]">

          <p
            className="
              text-sm
              font-semibold
              text-blue-900
            "
          >
            {value}
          </p>

        </div>

      ),
    },


    // ===================================================
    // DATE
    // ===================================================

    {
      key: 'date',

      label: t(
        'common.date'
      ),


      render: (value) => (

        <div
          className="
            flex
            items-center
            gap-2

            text-sm
            text-blue-500

            whitespace-nowrap
          "
        >

          <FiCalendar
            className="
              text-red-600
              flex-shrink-0
            "
            size={15}
          />


          <span>
            {formatDate(value)}
          </span>

        </div>

      ),
    },


    // ===================================================
    // LOCATION
    // ===================================================

    {
      key: 'location',

      label: t(
        'common.location'
      ),


      render: (value) => (

        <div
          className="
            flex
            items-center
            gap-2

            text-sm
            text-blue-500

            min-w-[150px]
          "
        >

          <FiMapPin
            className="
              text-blue-900
              flex-shrink-0
            "
            size={15}
          />


          <span className="truncate">

            {
              value ||
              t(
                'common.notSpecified'
              )
            }

          </span>

        </div>

      ),
    },


    // ===================================================
    // STATUS
    // ===================================================

    {
      key: 'is_upcoming',

      label: t(
        'common.status'
      ),


      render: (
        value,
        row
      ) => {

        const upcoming =
          Boolean(value) &&
          !row?.is_past;


        return (

          <span
            className={`
              inline-flex
              items-center
              gap-1.5

              px-2.5
              py-1

              rounded-full

              text-[11px]
              font-semibold

              ${
                upcoming
                  ? `
                    bg-blue-50
                    text-blue-700

                    border
                    border-blue-200
                  `
                  : `
                    bg-red-50
                    text-red-600

                    border
                    border-red-100
                  `
              }
            `}
          >

            <span
              className={`
                w-1.5
                h-1.5
                rounded-full

                ${
                  upcoming
                    ? 'bg-blue-500'
                    : 'bg-red-500'
                }
              `}
            />


            {
              upcoming
                ? t(
                    'events.upcoming'
                  )
                : t(
                    'events.past'
                  )
            }

          </span>

        );

      },
    },


    // ===================================================
    // ACTIONS
    // ===================================================

    {
      key: 'actions',

      label: t(
        'common.actions'
      ),


      render: (_, row) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          {/* EDIT */}

          <button
            type="button"

            onClick={() =>
              handleEdit(row)
            }

            className="
              w-8
              h-8

              flex
              items-center
              justify-center

              bg-blue-50
              text-blue-900

              rounded-lg

              hover:bg-blue-900
              hover:text-white

              transition-all
              duration-200
            "

            title={
              t('common.edit')
            }
          >

            <FiEdit2 size={14} />

          </button>


          {/* DELETE */}

          <button
            type="button"

            onClick={() =>
              handleDelete(
                row.id
              )
            }

            className="
              w-8
              h-8

              flex
              items-center
              justify-center

              bg-red-50
              text-red-600

              rounded-lg

              hover:bg-red-600
              hover:text-white

              transition-all
              duration-200
            "

            title={
              t('common.delete')
            }
          >

            <FiTrash2 size={14} />

          </button>

        </div>

      ),
    },

  ];


  // =====================================================
  // EVENT COUNTS
  // =====================================================

  const upcomingCount =
    events.filter(
      (event) =>
        event.is_upcoming &&
        !event.is_past
    ).length;


  const pastCount =
    events.filter(
      (event) =>
        event.is_past
    ).length;


  // =====================================================
  // RENDER
  // =====================================================

  return (

    <div className="w-full">


      {/* =================================================
          HEADER
      ================================================== */}

      <div
        className="
          flex
          flex-col

          sm:flex-row
          sm:items-center
          sm:justify-between

          gap-4
          mb-6
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-10
              h-10

              bg-blue-900
              text-white

              rounded-xl

              flex
              items-center
              justify-center

              shadow-sm
            "
          >

            <FiCalendar size={18} />

          </div>


          <div>

            <h1
              className="
                text-xl
                md:text-2xl

                font-bold
                text-blue-900
              "
            >
              {t(
                'events.management'
              )}
            </h1>


            <p
              className="
                text-xs
                md:text-sm

                text-blue-400
                mt-1
              "
            >
              {t(
                'events.subtitle'
              )}
            </p>

          </div>

        </div>


        {/* ADD EVENT */}

        <button
          type="button"

          onClick={handleAdd}

          className="
            h-10
            px-4

            inline-flex
            items-center
            justify-center
            gap-2

            bg-red-600
            text-white

            rounded-lg

            text-sm
            font-semibold

            shadow-sm

            hover:bg-red-700
            hover:shadow-md

            transition-all
            duration-200
          "
        >

          <FiPlus size={17} />


          {t(
            'events.addEvent'
          )}

        </button>

      </div>


      {/* =================================================
          SUMMARY CARDS
      ================================================== */}

      <div
        className="
          grid
          grid-cols-1
          sm:grid-cols-3

          gap-3
          mb-5
        "
      >


        {/* TOTAL EVENTS */}

        <div
          className="
            bg-white

            border
            border-blue-200

            rounded-xl
            p-4

            shadow-sm
          "
        >

          <p
            className="
              text-xs
              text-blue-400
            "
          >
            {t(
              'events.totalEvents'
            )}
          </p>


          <p
            className="
              text-2xl
              font-bold
              text-blue-900
              mt-1
            "
          >
            {events.length}
          </p>

        </div>


        {/* UPCOMING */}

        <div
          className="
            bg-white

            border
            border-blue-200

            rounded-xl
            p-4

            shadow-sm
          "
        >

          <p
            className="
              text-xs
              text-blue-400
            "
          >
            {t(
              'events.upcoming'
            )}
          </p>


          <p
            className="
              text-2xl
              font-bold
              text-blue-600
              mt-1
            "
          >
            {upcomingCount}
          </p>

        </div>


        {/* PAST */}

        <div
          className="
            bg-white

            border
            border-red-100

            rounded-xl
            p-4

            shadow-sm
          "
        >

          <p
            className="
              text-xs
              text-blue-400
            "
          >
            {t(
              'events.pastEvents'
            )}
          </p>


          <p
            className="
              text-2xl
              font-bold
              text-red-600
              mt-1
            "
          >
            {pastCount}
          </p>

        </div>

      </div>


      {/* =================================================
          EVENTS TABLE
      ================================================== */}

      <AdminCard
        className="
          overflow-hidden

          border
          border-blue-200

          shadow-sm
          rounded-xl
        "
      >

        {/* TABLE HEADER */}

        <div
          className="
            px-5
            py-4

            border-b
            border-blue-200

            flex
            items-center
            justify-between
          "
        >

          <div>

            <h2
              className="
                text-sm
                font-bold
                text-blue-900
              "
            >
              {t(
                'events.allEvents'
              )}
            </h2>


            <p
              className="
                text-xs
                text-blue-300
                mt-1
              "
            >

              {events.length}{' '}


              {
                events.length === 1
                  ? t(
                      'events.event'
                    )
                  : t(
                      'events.events'
                    )
              }{' '}


              {t(
                'events.found'
              )}

            </p>

          </div>

        </div>


        <AdminTable
          columns={columns}
          data={events}
          loading={loading}
        />

      </AdminCard>


      {/* =================================================
          CREATE / EDIT MODAL
      ================================================== */}

      <AdminModal
        isOpen={modalOpen}

        onClose={
          handleCloseModal
        }

        title={
          editingEvent
            ? t(
                'events.editEvent'
              )
            : t(
                'events.createEvent'
              )
        }
      >

        <form
          onSubmit={
            handleSubmit
          }
        >

          <div className="space-y-4">


            {/* ===========================================
                EVENT TITLE
            ============================================ */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >

                {t(
                  'events.eventTitle'
                )}


                <span
                  className="
                    text-red-600
                  "
                >
                  {' '}*
                </span>

              </label>


              <input
                type="text"

                name="title"

                value={
                  formData.title
                }

                onChange={
                  handleChange
                }

                placeholder={
                  t(
                    'events.enterEventTitle'
                  )
                }

                className="
                  w-full
                  h-11
                  px-3.5

                  border
                  border-blue-200

                  rounded-lg

                  text-sm
                  text-blue-900

                  outline-none

                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10

                  transition-all
                "

                required
              />

            </div>


            {/* ===========================================
                DESCRIPTION
            ============================================ */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                {t(
                  'events.description'
                )}
              </label>


              <textarea
                name="description"

                value={
                  formData.description
                }

                onChange={
                  handleChange
                }

                rows="4"

                placeholder={
                  t(
                    'events.descriptionPlaceholder'
                  )
                }

                className="
                  w-full
                  px-3.5
                  py-3

                  border
                  border-blue-200

                  rounded-lg

                  text-sm
                  text-blue-900

                  outline-none
                  resize-none

                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10

                  transition-all
                "
              />

            </div>


            {/* ===========================================
                DATE + LOCATION
            ============================================ */}

            <div
              className="
                grid
                grid-cols-1
                md:grid-cols-2
                gap-4
              "
            >


              {/* EVENT DATE */}

              <div>

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >

                  {t(
                    'events.eventDate'
                  )}


                  <span
                    className="
                      text-red-600
                    "
                  >
                    {' '}*
                  </span>

                </label>


                <div className="relative">

                  <input
                    type="date"

                    name="date"

                    value={
                      formData.date
                    }

                    onChange={
                      handleChange
                    }

                    className="
                      w-full
                      h-11
                      px-3.5

                      border
                      border-blue-200

                      rounded-lg

                      text-sm
                      text-blue-900

                      outline-none

                      focus:border-blue-900
                      focus:ring-2
                      focus:ring-blue-900/10

                      transition-all
                    "

                    required
                  />

                </div>


                <p
                  className="
                    text-[11px]
                    text-blue-300
                    mt-1.5
                  "
                >
                  {t(
                    'events.selectEventDate'
                  )}
                </p>

              </div>


              {/* LOCATION */}

              <div>

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >
                  {t(
                    'events.location'
                  )}
                </label>


                <div className="relative">

                  <FiMapPin
                    className="
                      absolute
                      left-3
                      top-1/2
                      -translate-y-1/2

                      text-blue-300
                    "
                    size={15}
                  />


                  <input
                    type="text"

                    name="location"

                    value={
                      formData.location
                    }

                    onChange={
                      handleChange
                    }

                    placeholder={
                      t(
                        'events.locationPlaceholder'
                      )
                    }

                    className="
                      w-full
                      h-11

                      pl-9
                      pr-3

                      border
                      border-blue-200

                      rounded-lg

                      text-sm
                      text-blue-900

                      outline-none

                      focus:border-blue-900
                      focus:ring-2
                      focus:ring-blue-900/10
                    "
                  />

                </div>

              </div>

            </div>


            {/* ===========================================
                IMAGE UPLOAD
            ============================================ */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >

                {
                  editingEvent
                    ? t(
                        'events.changeEventImage'
                      )
                    : t(
                        'events.eventImage'
                      )
                }

              </label>


              {
                !imagePreview ? (

                  <label
                    className="
                      min-h-[130px]

                      border-2
                      border-dashed
                      border-blue-200

                      rounded-xl

                      flex
                      flex-col
                      items-center
                      justify-center

                      cursor-pointer

                      bg-blue-50

                      hover:border-blue-400

                      transition-all
                    "
                  >

                    <FiUploadCloud
                      size={27}

                      className="
                        text-blue-900
                        mb-2
                      "
                    />


                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {t(
                        'events.clickUpload'
                      )}
                    </p>


                    <p
                      className="
                        text-[11px]
                        text-blue-300
                        mt-1
                      "
                    >
                      {t(
                        'events.imageFormats'
                      )}
                    </p>


                    <input
                      type="file"

                      accept="image/*"

                      onChange={
                        handleImageChange
                      }

                      className="hidden"
                    />

                  </label>

                ) : (

                  <div
                    className="
                      relative
                      w-full
                      h-[180px]

                      rounded-xl
                      overflow-hidden

                      bg-blue-50

                      border
                      border-blue-200
                    "
                  >

                    <img
                      src={
                        imagePreview
                      }

                      alt={
                        t(
                          'events.eventImage'
                        )
                      }

                      className="
                        w-full
                        h-full
                        object-cover
                      "
                    />


                    {/* REMOVE IMAGE */}

                    <button
                      type="button"

                      onClick={
                        removeSelectedImage
                      }

                      className="
                        absolute
                        top-2
                        right-2

                        w-8
                        h-8

                        bg-black/60
                        text-white

                        rounded-full

                        flex
                        items-center
                        justify-center

                        hover:bg-red-600

                        transition
                      "

                      title={
                        t(
                          'common.remove'
                        )
                      }
                    >

                      <FiX size={15} />

                    </button>


                    {/* CHANGE IMAGE */}

                    <label
                      className="
                        absolute
                        left-3
                        bottom-3

                        inline-flex
                        items-center
                        gap-2

                        px-3
                        py-2

                        bg-white
                        text-blue-900

                        rounded-lg

                        text-xs
                        font-semibold

                        shadow-md

                        cursor-pointer

                        hover:bg-blue-900
                        hover:text-white

                        transition
                      "
                    >

                      <FiImage />


                      {t(
                        'events.changeImage'
                      )}


                      <input
                        type="file"

                        accept="image/*"

                        onChange={
                          handleImageChange
                        }

                        className="hidden"
                      />

                    </label>

                  </div>

                )
              }


              {
                editingEvent &&
                !imageFile && (

                  <p
                    className="
                      text-[11px]
                      text-blue-300
                      mt-1.5
                    "
                  >
                    {t(
                      'events.keepCurrentImage'
                    )}
                  </p>

                )
              }

            </div>


            {/* ===========================================
                EVENT STATUS
            ============================================ */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-2
                "
              >
                {t(
                  'events.eventStatus'
                )}
              </label>


              <div
                className="
                  grid
                  grid-cols-2
                  gap-3
                "
              >


                {/* UPCOMING */}

                <label
                  className={`
                    cursor-pointer

                    flex
                    items-center
                    gap-3

                    p-3

                    rounded-xl
                    border

                    transition-all

                    ${
                      formData.is_upcoming
                        ? `
                          border-blue-300
                          bg-blue-50
                        `
                        : `
                          border-blue-200
                          bg-white
                        `
                    }
                  `}
                >

                  <input
                    type="checkbox"

                    checked={
                      formData.is_upcoming
                    }

                    onChange={(e) =>

                      setFormData(
                        (prev) => ({
                          ...prev,

                          is_upcoming:
                            e.target.checked,

                          is_past:
                            e.target.checked
                              ? false
                              : prev.is_past,
                        })
                      )

                    }

                    className="
                      w-4
                      h-4
                      accent-blue-600
                    "
                  />


                  <div>

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {t(
                        'events.upcoming'
                      )}
                    </p>


                    <p
                      className="
                        text-[10px]
                        text-blue-300
                      "
                    >
                      {t(
                        'events.futureEvent'
                      )}
                    </p>

                  </div>

                </label>


                {/* PAST */}

                <label
                  className={`
                    cursor-pointer

                    flex
                    items-center
                    gap-3

                    p-3

                    rounded-xl
                    border

                    transition-all

                    ${
                      formData.is_past
                        ? `
                          border-red-300
                          bg-red-50
                        `
                        : `
                          border-blue-200
                          bg-white
                        `
                    }
                  `}
                >

                  <input
                    type="checkbox"

                    checked={
                      formData.is_past
                    }

                    onChange={(e) =>

                      setFormData(
                        (prev) => ({
                          ...prev,

                          is_past:
                            e.target.checked,

                          is_upcoming:
                            e.target.checked
                              ? false
                              : prev.is_upcoming,
                        })
                      )

                    }

                    className="
                      w-4
                      h-4
                      accent-red-600
                    "
                  />


                  <div>

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {t(
                        'events.past'
                      )}
                    </p>


                    <p
                      className="
                        text-[10px]
                        text-blue-300
                      "
                    >
                      {t(
                        'events.completedEvent'
                      )}
                    </p>

                  </div>

                </label>

              </div>

            </div>

          </div>


          {/* =================================================
              MODAL FOOTER
          ================================================== */}

          <div
            className="
              mt-6
              pt-4

              border-t
              border-blue-200

              flex
              items-center
              justify-end
              gap-3
            "
          >


            {/* CANCEL */}

            <button
              type="button"

              onClick={
                handleCloseModal
              }

              disabled={
                submitting
              }

              className="
                h-10
                px-4

                border
                border-blue-200

                bg-white
                text-blue-400

                rounded-lg

                text-sm
                font-semibold

                hover:bg-blue-50

                disabled:opacity-50
                disabled:cursor-not-allowed

                transition
              "
            >
              {t(
                'common.cancel'
              )}
            </button>


            {/* SUBMIT */}

            <button
              type="submit"

              disabled={
                submitting
              }

              className="
                min-w-[110px]
                h-10
                px-5

                bg-red-600
                text-white

                rounded-lg

                text-sm
                font-semibold

                hover:bg-red-700

                disabled:opacity-50
                disabled:cursor-not-allowed

                transition-all
              "
            >

              {
                submitting
                  ? editingEvent
                    ? t(
                        'events.updating'
                      )
                    : t(
                        'events.creating'
                      )
                  : editingEvent
                  ? t(
                      'events.updateEvent'
                    )
                  : t(
                      'events.createEvent'
                    )
              }

            </button>

          </div>

        </form>

      </AdminModal>

    </div>

  );

};


export default AdminEvents;
